def transform(grid):
    g = np.array(grid)
    bg = 0 if (g == 0).any() else background(g)
    emit(g.copy(), "Initial canvas; objects are 8-connected single-colour shapes.")
    objs = objects(g, bg=bg, diagonal=True)
    out = g.copy()
    for o in objs:
        for c in objs:
            if c is o or c["colour"] == o["colour"] or c["size"] <= o["size"]:
                continue
            y0, x0, y1, x1 = c["box"]
            if all(y0 <= y <= y1 and x0 <= x <= x1 for y, x in o["cells"]):
                for y, x in o["cells"]:
                    out[y, x] = bg
                emit(out.copy(), f"Erase colour-{o['colour']} object lying inside the colour-{c['colour']} container.")
                break
    emit(out.copy(), "Final: all contained objects removed.")
    return out
